# 단계 모듈의 절 = 공통 모듈 목록의 맨 앞 넷(화면 `/workflow` 의 「공통 모듈」 · workflow.md) — 같은 함수에 일반 이름을 넣어 만든다(kind "stage").
# 공통 모듈 목록의 단계는 하는 문서(on)를 비운다 — 하는 문서는 그 단계를 조립한 워크플로우의 단계에만 있다(spec_워크플로우 ② §15 「문서마다 단위문서 TASK」)
COMMON = tuple(dict(id=mid, kind="stage", name=name, where=_STAGE_WHERE, does=does, steps=tuple(dict(s, on="") for s in make(*_GENERIC))) for mid, name, make, does in STAGE_MODULES) + COMMON
BY_JOB = {t["job"]: t for t in TASKS}
BY_COMMON = {c["id"]: c for c in COMMON}


def _mids(A):
    """조립한 정의의 배정 → 서는 단계 모듈 id(일반 차례) — 「문서 검토」 는 어느 문서든 골랐으면 · 나머지는 목적 문서가 골랐을 때(원본 문서는 「문서 검토」 만)."""
    return [m for m, *_ in STAGE_MODULES if m in A["target"] or (m == "stage_review" and m in A["source"])]


def _custom_does(S, D, A):
    """조립한 정의의 묶음 설명 → {묶음 id: 글} — 실제 배정 그대로(고른 문서 · LLM 검증·보완을 할 문서 · 작성 지침을 저장하나 · 앞의 단계). 등록부(assemble)와 화면 실행(GET /api/tasks 의 does)이 같은 글을 쓴다.
    「내용 넣기」 는 「구성 맞추기」 를 안 골랐으면 「앞의 두 단계」 를 말하지 않고 자리 연결이 서는 조건(FILL_NO_FIT — 조립 화면의 경고와 같은 글)을 · 「문서 정리」 는 「문서 검토」 가 없으면 「헤딩 · 표 분석」 줄을 가리키지 않는다."""
    from app import custom_tasks
    G, name = custom_tasks.STAGE_GROUP, {"source": S, "target": D}
    who = lambda rs: f"두 문서({S} · {D})" if len(rs) == 2 else f"{dict(ROLES)[rs[0]]}({name[rs[0]]})"  # noqa: E731
    heads, llm, mids = [r for r in custom_tasks.ROLES if "stage_review" in A[r]], list(A["llm"]), _mids(A)
    fit, out = "stage_fit" in A["target"], {}
    if heads:
        out[G["stage_review"]] = (f"{who(heads)}의 헤딩 · 표 분석({'없는 문서만' if len(heads) == 2 else '없으면'} — 스크립트)" + (" → 양식의 작성 지침을 헤딩/표별로 저장" if "target" in heads else "")
                                  + (f" → {'두 문서' if len(llm) == 2 else who(llm)}의 LLM 검증·보완(유료 · 몇 분 — LLM 을 쓸 수 없으면 건너뜀)" if llm else "") + " · 문서는 안 바뀜")
    if fit:
        out[G["stage_fit"]] = (f"프로젝트 구성 추출({S} 기준 — 추출하거나 불러와 프로젝트에 저장 · 「구성 불러오기」 는 선택) → {D}의 프로젝트 구성 반영(절 · 표 행 · 표 열 — 구조만) → "
                               f"다시 문서 검토({D}의 헤딩 · 표 다시 분석 → LLM 검증·보완) · 내용은 넣지 않음")
    if "stage_fill" in A["target"]:
        before = [_STAGE_BY[m][1] for m in mids[:mids.index("stage_fill")]]
        out[G["stage_fill"]] = (f"두 문서의 자리를 잇고(자리 연결 — LLM 검토 포함) {S}의 내용을 {D}의 그 자리에 넣음(넣기 계획 → 내용 반영 · 서식 맞춤) — "
                                + (f"앞의 {'두 ' if len(before) == 2 else ''}단계({' · '.join(before)})를 마친 문서끼리만" if fit
                                   else (f"앞의 단계({before[0]})를 마친 뒤에 · " if before else "") + f"「구성 맞추기」 를 고르지 않은 워크플로우라 {FILL_NO_FIT}"))
    if "stage_clean" in A["target"]:
        out[G["stage_clean"]] = (f"{D} 서식이 글쓴이에게 주는 안내(작성 요령 표 · 「<참고 N>」 자료 · ※ 안내 · 각주 번호)를 지움(내용은 남김) — 지우기 전에 작성 지침을 헤딩/표별로 저장"
                                 + ("(「헤딩 · 표 분석」 줄의 「작성 지침」 으로 봄)" if heads else ""))
    return out


def _custom_output(S, D, A):
    """조립한 정의의 산출물 — 실제로 바뀌는 것(목적 문서가 받는 단계)에서: 내용 넣기 > 구성 맞추기 > 문서 정리 차례로 · 문서 검토만이면 분석 · 검증한 문서(문서는 안 바뀜)."""
    dst, clean = A["target"], " · 양식 안내(작성요령)를 지움" if "stage_clean" in A["target"] else ""
    if "stage_fill" in dst:
        return f"원본({S})의 내용이 들어간 {D} 초안" + ("(구조를 프로젝트 구성에 맞춤)" if "stage_fit" in dst else "") + clean
    if "stage_fit" in dst:
        return f"구조를 프로젝트 구성에 맞춘 {D}" + clean
    if clean:
        return f"양식 안내(작성요령)를 지운 {D}(지우기 전에 작성 지침을 헤딩/표별로 저장)"
    nm = {"source": S, "target": D}
    heads = [r for r in ("source", "target") if "stage_review" in A[r]]
    llm = [r for r in heads if r in A["llm"]]
    if not heads:   # 고른 것이 없는 정의는 서지 않는다(custom_tasks 가 거른다) — 지켜 둠
        return f"고른 단계를 마친 {D}"
    notes = ([f"LLM 검증·보완은 {nm[llm[0]]}"] if llm and llm != heads else []) + ["문서는 안 바뀜"]
    docs, more = (("두 문서", [f"{S} · {D}"]) if len(heads) == 2 else (nm[heads[0]], []))
    return f"헤딩 · 표를 {'분석 · 검증한' if llm == heads else '분석한'} {docs}({' — '.join(more + [' · '.join(notes)])})"


# ---- 줄 목록으로 조립한 정의(v2 — spec_워크플로우 ② §18-5 · §18-12 ⑤: app/custom_tasks.py 의 flow) → 등록부 꼴. 줄의 글은 일반 단계 함수(_st_*)가 만든 줄에서 key 로 집고(한 곳),
# 줄의 하는 문서는 정의가 고른 대로 · 묶음 = 정의의 묶음(id g1 … · 번호는 차례로 「N단계」 · 이름은 정의의 것) · 맨 앞 묶음에 「준비」. 실행기 · 상태는 줄 key 로 단위를 찾는다(묶음의 module 은 한 단계의 줄만 든 묶음에만).
def _hand_step(s):
    """사람이 하는 일 줄(② §18-7 · §18-12 ⑦) — 줄 id(hand1 …) · 이름 · 사람에게 보일 글 · 가리키는 도구 · 하는 문서."""
    on = "both" if len(s["on"]) == 2 else (s["on"][0] if s["on"] else "flow")
    note = s.get("note") or "사람이 할 일입니다"
    return _beside(_s(s["id"], s.get("name") or "사람이 하는 일", "human", note + " — 마친 뒤 그 줄의 「했음」 을 누르면 다음 줄로 갑니다.", uses=(s["tool"],) if s.get("tool") else (), on=on,
                      need="사람의 확인.", done="사람이 「했음」 을 눌렀을 때.", stop="이 줄에 오면 실행이 멈추고 사람을 기다립니다(실패가 아닙니다)."), s)


def _beside(step, s):
    """정의의 줄 s 가 앞 줄과 같은 차례(조립 화면의 같은 행 — `beside`)면 등록부 꼴의 단계에도 그 표시를 싣는다(실행기가 그 두 줄을 함께 돌지 본다: workflow_state.lines · workflow_exec._together)."""
    return dict(step, beside=True) if s.get("beside") else step


def _assemble_gather(c):
    """취합형으로 조립한 정의(shape gather — 원본 = 기관 문서 여럿 → 목적 = 취합본 하나: spec_워크플로우 ② §18-13 갈래 「라」 ⓶) → 등록부의 워크플로우 꼴.
    줄의 글 · 시작 점검 · 문서 역할은 붙박이 「사업계획서 취합」 의 것 그대로(그 줄들이 취합형의 실행 단위다) · 묶음은 정의의 것(g1 … — 번호는 1부터) · 맨 앞 묶음에 「준비」.
    구성의 기준 = 목적 문서(취합본 — 붙박이와 같다)."""
    base = BY_JOB["plan_merge"]
    made = {s["key"]: s for g in base["stages"] for s in g["steps"]}
    stages = []
    for i, g in enumerate(c["flow"]):
        steps = [dict(made["files"])] if i == 0 else []
        for s in g["steps"]:
            steps.append(_hand_step(s) if s["unit"] == "hand" else _beside(dict(made[s["unit"]]), s))
        names = [x["name"] for x in steps if x["key"] != "files"]
        does = JOIN.join(names) + (" · 목적 문서(취합본)가 바뀜" if any(x["change"] == "doc" and x["key"] != "drop" for x in steps) else " · 문서는 안 바뀜")   # 끌어 넣기는 사람이 할 때만 바뀐다
        stages.append(_g(g["id"], steps, no=f"{i + 1}단계", name=g["name"], does=does))
    return dict(job=c["key"], custom=True, v=2, name=c["name"], desc=c["desc"] or custom_desc(c), premise=c["premise"], premise_from="plan_merge", base="target",
                stages=tuple(stages), entry=base["entry"], roles=tuple(dict(r) for r in base["roles"]),
                inputs=base["inputs"], output=base["output"],
                note="줄 목록으로 조립한 취합 워크플로우입니다 — 정한 차례대로 서버에서 진행합니다. 기관 문서(원본)는 바뀌지 않습니다.")


def _assemble_single(c):
    """문서 하나로 조립한 정의(shape single — 목적 문서 하나 · 원본 없음: spec_워크플로우 ② §18-13 걸음 6 — 2026-11-20 사용자 「그리고 문서 하나는 왜 안되냐?」 → 답 「조립한 것만 서버로」) → 등록부의 워크플로우 꼴.
    실행 단위의 가족 = single(`units` — app/workflow_units.py SINGLE: 붙박이 「사업계획서 양식 표준화」 · 「연차보고서 양식 맞추기」 와 같은 줄) · 문서 역할 = 그 문서 종류의 붙박이의 것 그대로(목적 문서 하나 — 원본 역할 없음).
    줄의 글 = 그 종류의 붙박이 줄에서 key 로(거기 없는 줄은 양식 표준화의 것 — 연차보고서에 헤딩 · 표 줄을 놓았을 때) · 줄의 on 은 붙박이처럼 빈 글(그 문서가 곧 목적 문서: workflow_state.roles_on) —
    사람이 하는 일도. 묶음은 정의의 것(g1 … — 번호는 1부터) · 맨 앞 묶음의 첫 줄에 「준비」(open). 시작 점검 · 받는 문서 · 산출물은 그 종류의 붙박이의 것."""
    from app import custom_tasks
    base = BY_JOB[custom_tasks.base_of(c)]   # 그 문서 종류의 붙박이(사업계획서 = plan_fit · 연차보고서 = report_fit)
    made = {s["key"]: s for g in BY_JOB["plan_fit"]["stages"] for s in g["steps"]}
    made.update({s["key"]: s for g in base["stages"] for s in g["steps"]})
    stages = []
    for i, g in enumerate(c["flow"]):
        steps = [dict(made["open"])] if i == 0 else []
        for s in g["steps"]:
            steps.append(dict(_hand_step(s), on="") if s["unit"] == "hand" else dict(made[s["unit"]]))
        names = [x["name"] for x in steps if x["key"] != "open"]
        does = JOIN.join(names) + (" · 문서가 바뀜" if any(x["change"] == "doc" and not x["optional"] for x in steps) else " · 문서는 안 바뀜")   # 선택 줄(템플릿 관계 · 표 점검)은 사람이 할 때만 바뀐다
        stages.append(_g(g["id"], steps, no=f"{i + 1}단계", name=g["name"], does=does))
    return dict(job=c["key"], custom=True, v=2, units="single", name=c["name"], desc=c["desc"] or custom_desc(c), premise=c["premise"], premise_from=base["job"],
                stages=tuple(stages), entry=base["entry"], roles=tuple(dict(r) for r in base["roles"]),
                inputs=base["inputs"], output=base["output"],
                note="줄 목록으로 조립한 문서 하나 워크플로우입니다 — 정한 차례대로 서버에서 진행합니다.")


def _assemble_flow(c):
    from app import custom_tasks
    if c.get("shape") == "gather":
        return _assemble_gather(c)
    if c.get("shape") == "single":   # 문서 하나 — 이관형으로 짓지 않는다(원본이 없다 · 줄 key 가 이관의 것과 겹친다: plan · apply · heads)
        return _assemble_single(c)
    S, D = custom_tasks.FILES[c["source"]], custom_tasks.FILES[c["target"]]
    on = {}
    for g in c["flow"]:
        for s in g["steps"]:
            on.setdefault(s["unit"], set()).update(s["on"])
    A, fit, review = custom_tasks.guess_assign(c["flow"]), "division" in on, "heads" in on
    opts = {"stage_review": dict(src="source" in on.get("heads", ()), dst="target" in on.get("heads", ()), llm=tuple(r for r in ("source", "target") if r in on.get("headsLlm", ())) or ("source",), fit=fit),
            "stage_fit": dict(take=True),   # 조립에 놓는 도구 「넣을 구성 선택」 의 줄 글까지(_take_step — 표준 차례에는 없다)
            "stage_fill": dict(fit=fit, review=review), "stage_clean": dict(review=review, fill="apply" in on)}
    made = {}
    for mid, _name, make, _does in STAGE_MODULES:
        o = opts.get(mid, {})
        if mid == "stage_review" and not (o["src"] or o["dst"]):
            o = {**o, "src": True}   # 그 정의에 헤딩 · 표 분석이 없어도 「LLM 검증·보완」 의 글은 짓는다(쓰이는 줄만 집는다)
        for s in make(S, D, **o):
            made.setdefault(s["key"], (mid, s))
    if "headsLlm" in on and "headsLlm" not in made:   # 「LLM 검증·보완」 을 「헤딩 · 표 분석」 이 없는 문서에 놓은 정의(조립 검사는 경고로 지나간다 — 분석이 없으면 실행이 스크립트로 먼저 한다) — 그 줄의 글을 그 문서의 것으로 따로 짓는다
        r = on["headsLlm"]   # (전에는 여기서 KeyError — 그 정의를 저장하면 목록 · /workflow 가 500 이었다: 2026-11-20)
        made["headsLlm"] = ("stage_review", next(s for s in _st_review(S, D, src="source" in r, dst="target" in r, llm=tuple(x for x in ("source", "target") if x in r), fit=fit) if s["key"] == "headsLlm"))
    stages, no = [], {}
    for i, g in enumerate(c["flow"]):
        steps, homes = [_relay_files()] if i == 0 else [], set()
        for s in g["steps"]:
            if s["unit"] == "hand":
                steps.append(_hand_step(s))
                homes.add("hand")
                continue
            mid, base = made[s["unit"]]
            homes.add(mid)
            no.setdefault(custom_tasks.STAGE_GROUP[mid], f"{i + 1}단계")
            o = s["on"]
            if "source" in o and s["unit"] in ("division", "reheads", "reheadsLlm", "guide"):   # 원본 문서에도 놓은 구조 · 정리 줄 — 글을 그 줄이 고른 문서의 것으로(② §18-2 「원본 문서에 놓는 줄」)
                base = next(x for x in _STAGE_BY[mid][2](S, D, **{**{k: v for k, v in opts.get(mid, {}).items() if k != "take"}, "who": tuple(o)}) if x["key"] == s["unit"])
            steps.append(_beside(dict(base, on=base["on"] if base["on"] in ("flow", "pair") else ("both" if len(o) == 2 else o[0])), s))
        names = [x["name"] for x in steps if x["key"] != "files"]
        changed = [title for role, title in ROLES if any(x["change"] == "doc" and touches(x, role) for x in steps)]   # 이 묶음이 바꾸는 문서(원본 → 목적 줄은 목적 문서만 바꾼다)
        does = JOIN.join(names) + (f" · {' · '.join(changed)}가 바뀜" if changed else " · 문서는 안 바뀜")
        stages.append(_g(g["id"], steps, no=f"{i + 1}단계", name=g["name"], does=does, module=next(iter(homes)) if len(homes) == 1 and "hand" not in homes else None))
    roles = (_role("source", S, c["source"]), _role("target", D, c["target"]))
    src_change = list(dict.fromkeys(x["name"] for g in stages for x in g["steps"] if x["change"] == "doc" and x["on"] in ("source", "both")))   # 원본 문서를 바꾸는 줄(사용자가 원본 문서 칸에 놓은 것)
    if src_change:   # 원본 문서가 바뀌는 정의 — 「바뀌지 않는 문서」 라는 글을 싣지 않는다
        for g in stages:
            g["steps"] = tuple(dict(x, does=x["does"].replace("(원본 — 이 워크플로우에서 바뀌지 않는 문서)", "(원본)")) for x in g["steps"])
    return dict(job=c["key"], custom=True, v=2, name=c["name"], desc=c["desc"] or custom_desc(c), premise=c["premise"], premise_from=custom_tasks.BASE,
                base=custom_tasks.BASE_ROLE if "config" in on else None, stages=tuple(stages), entry=_relay_entry(no, A, roles), roles=roles,
                inputs=f"{S}(원본 문서) + {D}(목적 문서)", output=_custom_output(S, D, A),
                note="줄 목록으로 조립한 워크플로우입니다 — 정한 차례대로 서버에서 진행합니다. "
                     + (f"{S}(원본)도 바뀝니다 — 원본 문서에 놓은 줄: {' · '.join(src_change)}." if src_change else f"{S}(원본)는 바뀌지 않습니다."))


def custom_desc(c):
    """조립한 정의(app/custom_tasks.py 의 줄) → 한 줄 설명 — 실제로 고른 묶음을 따라 짓는다(한 줄 설명을 비운 정의의 등록부 desc · GET /api/tasks 의 descAuto ·
    첫 화면 가이드의 후보 설명이 같이 쓴다). 「내용 넣기」 가 있을 때만 「옮깁니다」 · 없으면 실제로 하는 일(구조 맞춤 · 안내 지움 · 검토). 줄 목록 정의(v2)는 줄에서 읽은 배정으로 같은 글."""
    from app import custom_tasks
    if c.get("shape") == "gather":   # 취합형 — 기관 문서(여럿)의 내용을 취합본 하나에(넣는 줄이 없으면 실제로 하는 일: 구성 · 배포 기준본까지)
        keys = {s["unit"] for g in c.get("flow") or () for s in g["steps"]}
        what = ("기관이 나눠 쓴 문서(여럿)의 내용을 취합본 하나로 모읍니다" if "apply" in keys else "취합본의 구조를 프로젝트 구성에 맞추고 기관에 나눠 줄 배포 기준본을 만듭니다" if "frame" in keys
                else "취합본의 프로젝트 구성을 정합니다")
        return what + " — 정한 차례대로 진행합니다."
    if c.get("shape") == "single":   # 문서 하나 — 원본이 없다: 그 문서에 실제로 하는 일(놓은 줄에서 — 구조 맞춤 · 헤딩 · 템플릿 · 서식 · 표)
        keys = {s["unit"] for g in c.get("flow") or () for s in g["steps"]}
        parts = [x for x in ((("절 · 표 행 · 표 열을 프로젝트 구성에 맞추고", "절 · 표 행 · 표 열을 프로젝트 구성에 맞춥니다") if "apply" in keys
                              else ("프로젝트 구성을 정하고", "프로젝트 구성을 정합니다") if keys & {"read", "load", "values"} else None),
                             (("헤딩 · 템플릿을 뽑아 서식을 템플릿에 맞추고", "헤딩 · 템플릿을 뽑아 서식을 템플릿에 맞춥니다") if "adjust" in keys
                              else ("헤딩 · 템플릿을 뽑고", "헤딩 · 템플릿을 뽑습니다") if keys & {"heads", "headsLlm"} else None),
                             ("표의 칸 역할을 라벨로 붙이고", "표의 칸 역할을 라벨로 붙입니다") if keys & {"tables", "tablesLlm"} else None) if x]   # (이어지는 꼴, 맺는 꼴) — 붙박이 「양식 표준화」 의 묶음 설명과 같은 말
        D = custom_tasks.kind_name(c["target"])
        if not parts:   # 사람이 하는 줄만 놓은 정의
            return f"{D} 하나에 놓은 줄을 정한 차례대로 진행합니다."
        return f"{D} 하나의 " + " ".join([a for a, _b in parts[:-1]] + [parts[-1][1]]) + " — 정한 차례대로 진행합니다."
    if c.get("flow") is not None:
        text = custom_desc({**c, "flow": None, "assign": custom_tasks.guess_assign(c["flow"])}).replace("고른 단계만 진행합니다", "정한 차례대로 진행합니다")
        names = custom_tasks.unit_names(base=True)   # 설명 글 · 만든 글 속의 이름은 기본 이름(사람이 고친 도구 이름을 얹지 않는다 — ② §18-19)
        src = list(dict.fromkeys(names.get(s["unit"], s["unit"]) for g in c["flow"] for s in g["steps"] if "source" in s["on"] and s["unit"] in ("division", "guide")))   # 원본 문서를 바꾸는 줄(원본 문서 칸에 놓은 것)
        return text + (f" 원본 문서({custom_tasks.FILES[c['source']]})도 바꿉니다 — {' · '.join(src)}." if src else "")
    S, D, A = custom_tasks.FILES[c["source"]], custom_tasks.FILES[c["target"]], c["assign"]
    dst, fit, clean = A["target"], "stage_fit" in A["target"], "stage_clean" in A["target"]
    if "stage_fill" in dst:
        what = f"{S}의 내용을 {D}로 옮깁니다"
    elif fit:
        what = f"{D}의 구조를 프로젝트 구성({S} 기준)에 " + ("맞추고 양식 안내(작성요령)를 지웁니다" if clean else "맞춥니다")
    elif clean:
        what = f"{D}의 양식 안내(작성요령)를 지웁니다"
    else:
        heads = [r for r in custom_tasks.ROLES if "stage_review" in A[r]]
        what = (f"두 문서({S} · {D})" if len(heads) == 2 else f"{dict(ROLES)[heads[0]]}({S if heads[0] == 'source' else D})" if heads else D) + "의 헤딩 · 표를 검토합니다(문서는 안 바뀜)"
    return what + " — 고른 단계만 진행합니다."


def assemble(c):
    """조립한 정의 하나(app/custom_tasks.py 의 줄 — ② §14) → 등록부의 워크플로우 꼴. 고른 단계를 일반 단계의 차례로 조립한다 — 번호는 1부터 다시, 묶음 id 는 이관 실행의 것(review · frame · map · clean),
    맨 앞 묶음에 「준비」(문서 고르기 — 워크플로우 전체)를 둔다. 묶음 설명 · 산출물 · 한 줄 설명(비웠을 때)은 실제 배정에서 짓는다(_custom_does · _custom_output · custom_desc —
    화면 실행도 GET /api/tasks 의 does 로 같은 글을 쓴다). 시작 점검은 붙박이 이관의 것을 이 조립의 묶음 번호로 짓는다(_relay_entry — 없는 묶음의 일만 보는 항목은 뺌).
    구성의 기준(base)은 목적 문서에 「구성 맞추기」 가 있을 때만 원본 문서다(없으면 None — 「구성의 기준」 을 적지 않는다).
    문서마다 단위문서 TASK(spec_워크플로우 ② §15 「문서마다 단위문서 TASK」): 「문서 검토」 묶음은 어느 문서든 골랐으면 서고, 그 안의 「헤딩 · 표 분석」 은 고른 문서 ·
    「LLM 검증·보완」 은 assign.llm 의 문서(닿는 문서가 없는 단계는 서지 않는다). 나머지 묶음은 목적 문서가 골랐을 때 선다(원본 문서는 「문서 검토」 만 — 원본은 바뀌지 않는다).
    저장소(이 PC 의 사용자 설정)의 것이라 workflow.md · tasks/ 에는 들지 않는다 — 글은 task_markdown(그 키)이 바로 만든다(작업 진행 에이전트의 참조 글).
    줄 목록 정의(v2 — c["flow"])는 _assemble_flow(정의의 묶음 › 줄 그대로)."""
    from app import custom_tasks
    if c.get("flow") is not None:
        return _assemble_flow(c)
    S, D, A = custom_tasks.FILES[c["source"]], custom_tasks.FILES[c["target"]], c["assign"]
    fit, review = "stage_fit" in A["target"], any("stage_review" in A[r] for r in custom_tasks.ROLES)
    opts = {"stage_review": dict(src="stage_review" in A["source"], dst="stage_review" in A["target"], llm=tuple(A["llm"]), fit=fit),
            "stage_fill": dict(fit=fit, review=review), "stage_clean": dict(review=review, fill="stage_fill" in A["target"])}
    does, mids = _custom_does(S, D, A), _mids(A)
    stages = tuple(_stage(mid, custom_tasks.STAGE_GROUP[mid], f"{i + 1}단계", S, D, does=does[custom_tasks.STAGE_GROUP[mid]], first=(_relay_files(),) if i == 0 else (), **opts.get(mid, {}))
                   for i, mid in enumerate(mids))
    no = {custom_tasks.STAGE_GROUP[mid]: f"{i + 1}단계" for i, mid in enumerate(mids)}   # 이 조립의 묶음 번호(화면 taskStagesSync · taskStageName 과 같은 셈)
    roles = (_role("source", S, c["source"]), _role("target", D, c["target"]))   # 시작 점검의 문서 이름 · 구성의 기준(_relay_entry)도 이 역할에서 — 흐름 줄과 같은 글
    return dict(job=c["key"], custom=True, name=c["name"], desc=c["desc"] or custom_desc(c), premise=c["premise"], premise_from=custom_tasks.BASE,
                base=custom_tasks.BASE_ROLE if fit else None, stages=stages, entry=_relay_entry(no, A, roles),
                roles=roles,
                inputs=f"{S}(원본 문서) + {D}(목적 문서)", output=_custom_output(S, D, A),
                note=f"단계의 뜻과 실행은 일반 단계 그대로이고, 고른 단계만 섭니다. {S}(원본)는 바뀌지 않습니다.")   # 화면의 「조립」 · 「전제」 줄과 겹치는 말은 적지 않는다(화면에 그대로 보이는 글 — md 꼴 없이)


def custom():
    """화면에서 조립한 워크플로우들(app/custom_tasks.py — ② §14) → 등록부의 꼴(assemble · 만든 차례)."""
    from app import custom_tasks
    return [assemble(c) for c in custom_tasks.all()]


def task_of(job):
    """키 → 등록부의 워크플로우(붙박이 BY_JOB · 조립한 것 — assemble) | None."""
    if job in BY_JOB:
        return BY_JOB[job]
    from app import custom_tasks
    c = custom_tasks.get(job)
    return assemble(c) if c else None


def picked_line(c):
    """전제를 물려받은 조립한 워크플로우의 한 줄 — app/job_prompts.py 가 물려받은 전제 글(jobs/plan_to_report.md)의 맨 앞에 넣는다(그 워크플로우의 LLM 호출이 모두 읽는다):
    문서마다 고른 단계와 「전제의 단계 설명 가운데 고르지 않은 단계는 하지 않는다」(전제 글은 붙박이 이관의 네 단계를 모두 적고 있다).
    문서마다 고른 단계는 차례대로 「 › 」(JOIN — 다음: spec_워크플로우 ② §15 「이음 기호」 · 조립 화면의 「직접 고른 단계」 와 같은 기호)로 잇는다."""
    from app import custom_tasks
    if c.get("flow") is not None:   # 줄 목록 정의(v2) — 묶음마다 줄 차례 그대로
        fam = custom_tasks.family_of(c.get("shape") or "relay")   # 줄 이름은 그 틀의 것(문서 하나 = 그 문서 종류의 붙박이 줄 이름 — 줄 key 가 이관의 것과 겹친다)
        names = custom_tasks.unit_names(fam, c["target"] if fam == "single" else "", base=True)   # LLM 이 읽는 글 — 기본 이름(전제 글이 그 이름으로 적혀 있다: ② §18-19)
        got = " / ".join(f"{g['name']}: " + JOIN.join("「" + (s.get("name") or names.get(s["unit"], s["unit"])) + "」" for s in g["steps"]) for g in c["flow"])
        return f"이 워크플로우는 줄 목록으로 조립한 것 — 정한 차례: [{got}] · 전제의 단계 설명 가운데 이 차례에 없는 일은 하지 않는다."
    A, name = c["assign"], {"source": custom_tasks.FILES[c["source"]], "target": custom_tasks.FILES[c["target"]]}

    def one(r):
        got = JOIN.join("「" + _STAGE_BY[m][1] + ("(LLM 검증·보완 포함)" if m == "stage_review" and r in A["llm"] else "") + "」" for m in A[r])
        return f"{dict(ROLES)[r]}({name[r]}): {got or '없음'}"
    return f"이 워크플로우는 조립한 것 — 고른 단계: [{one('source')} / {one('target')}] · 전제의 단계 설명 가운데 고르지 않은 단계는 하지 않는다."


def assembled(module):
    """그 단계 모듈을 조립한 TASK 의 키들(차례대로)."""
    return [t["job"] for t in TASKS if any(g.get("module") == module for g in _groups(t))]


def _groups(t):
    return t.get("stages") or ()


def _roles(t):
    """워크플로우의 문서 역할들(차례 = 원본 → 목적 — spec_워크플로우 ② §15 「문서마다 단위문서 TASK」). 문서 하나인 워크플로우는 목적 문서 하나."""
    return tuple(t.get("roles") or ())


def _many(t):
    """원본 문서가 여럿인가(취합 — 원본 문서마다 같은 단위문서 TASK 를 되풀이)."""
    return any(r["many"] for r in _roles(t) if r["role"] == "source")


def touches(s, role, single=False):
    """단계 s 가 그 역할의 문서에 닿는가 — on 이 그 역할 · both(문서마다 같은 일) · 목적 문서면 pair(원본 → 목적 잇기 — 목적 문서가 받음)도.
    문서 하나인 워크플로우(single)는 on 이 빈 단계가 모두 그 문서(목적 문서)의 것이다(원본 문서가 없다)."""
    if single:
        return role == "target" and s["on"] == ""
    return s["on"] in (role, "both") or (role == "target" and s["on"] == "pair")


def unit(t, role):
    """그 역할 문서의 단위문서 TASK → [(묶음, [단계 …])] — 묶음 차례대로, 그 문서에 닿는 단계가 하나라도 있는 묶음만(② §15). listing() 의 roles[].unit 과 글(workflow.md · TASK 문서)이 같이 쓴다.
    워크플로우 전체의 단계(on flow)는 어느 문서의 것도 아니다 — flow_of."""
    single = len(_roles(t)) < 2
    return [(g, hit) for g in _groups(t) for hit in [[s for s in g["steps"] if touches(s, role, single)]] if hit]


def flow_of(t):
    """워크플로우 전체의 단계(on flow — 준비 · 구성 불러오기 · 프로젝트 구성 추출: 문서마다가 아니라 한 번) → [(묶음, [단계 …])] — 묶음 차례 · 그런 단계가 있는 묶음만. listing() 의 flow 와 글이 같이 쓴다."""
    return [(g, hit) for g in _groups(t) for hit in [[s for s in g["steps"] if s["on"] == "flow"]] if hit]


def _names(t):
    """워크플로우의 (원본 문서 이름, 목적 문서 이름, 원본이 여럿인가) — 단계의 onText(on_text)가 쓴다(문서 하나인 워크플로우는 원본 이름이 "")."""
    by = {r["role"]: r for r in _roles(t)}
    return (by.get("source") or {}).get("name", ""), (by.get("target") or {}).get("name", ""), _many(t)


def steps():
    """등록부의 모든 단계 → [(어디: "task:<job>" | "common:<id>", 단계)] — 시험과 listing 이 같이 쓴다."""
    out = [(f"task:{t['job']}", s) for t in TASKS for g in _groups(t) for s in g["steps"]]
    return out + [(f"common:{c['id']}", s) for c in COMMON for s in c["steps"]]


def module_path(name):
    """모듈 이름 → 저장소 기준 경로(`app/<이름>.py` · 묶음이면 `app/<이름>/`) | None(없음)."""
    if (APP / f"{name}.py").is_file():
        return f"app/{name}.py"
    return f"app/{name}/" if (APP / name / "__init__.py").is_file() else None


_DOCS = {}


def _doc(name):
    """모듈 설명의 첫 줄(파일의 docstring) — 화면의 모듈 이름 옆 글. 못 읽으면 빈 글. 파일이 바뀌면 다시 읽는다."""
    path = module_path(name)
    if not path:
        return ""
    p = ROOT / path / "__init__.py" if path.endswith("/") else ROOT / path
    try:
        stamp = p.stat().st_mtime
        if _DOCS.get(name, (None, ""))[0] != stamp:
            _DOCS[name] = (stamp, ((ast.get_docstring(ast.parse(p.read_text(encoding="utf-8"))) or "").strip().splitlines() or [""])[0].strip()[:300])
        return _DOCS[name][1]
    except (OSError, SyntaxError, ValueError):
        return ""


def _agents():
    """에이전트 id → {id, no, name, group, role, run, model} — 등록부·설정(app/agents.py)에서. 못 읽어도 페이지는 열린다(빈 사전)."""
    try:
        from app import agents
        return {a["id"]: {"id": a["id"], "no": a["no"], "name": a["name"], "group": a["group"], "role": a["role"], "run": a["runText"], "model": a["model"]} for a in agents.listing()["agents"]}
    except Exception:  # noqa: BLE001 — 설정 파일·LLM 설정이 깨져도 지도는 보인다
        return {}


def _spec(spec):
    return {"file": f"spec/{spec[0]}", "at": spec[1]} if spec else None


def entry(t):
    """TASK 의 시작 점검을 때(WHEN)마다 묶어 → [(when, 이름, 한 줄, [항목 …])] — 항목이 있는 때만(준비 중인 TASK 는 빈 목록). 화면 · 글 · 시험이 같이 쓴다."""
    return [(w, name, note, items) for w, name, note in WHEN for items in [[c for c in t.get("entry") or () if c["when"] == w]] if items]


def _shown(t, family=None):
    """그 워크플로우(등록부의 꼴)에 사람이 화면에서 고친 도구 이름을 얹은 사본(② §18-19 「도구 이름 고치기」 — app/tool_names.py) · 고친 것이 없으면 받은 것 그대로.
    **화면으로 나가는 문에만 쓴다**(등록부 응답 listing · 실행 층이 읽는 정의 shown_of) — 만든 글(markdown · task_markdown)은 기본 이름 그대로다(어느 PC 에서나 같은 글). family = 틀을 아는 곳이 준다(단계 = 이관형의 줄)."""
    from app import tool_names, workflow_state
    return tool_names.apply(t, family or workflow_state.family(t))


def shown_of(job):
    """키 → 사람이 고친 도구 이름을 얹은 워크플로우 꼴(붙박이 · 조립한 것) | None — 워크플로우 실행 층이 읽는 정의(workflow_state.definition: 실행 상태 · 실행 기록의 줄 이름 — ② §18-19).
    만든 글 · 프롬프트를 짓는 곳은 task_of(기본 이름)를 쓴다."""
    t = task_of(job)
    return _shown(t) if t else None


def _step(s, ags, names=("", "", False)):
    return {"key": s["key"], "no": s["no"], "name": s["name"], "baseName": s.get("baseName", ""),   # baseName = 사람이 이름을 고친 도구의 기본 이름(안 고쳤으면 "" — ② §18-19)
            "by": list(s["by"]), "does": s["does"], "out": s["out"], "change": s["change"], "auto": s["auto"], "optional": s["optional"], "soon": s["soon"],
            "on": s["on"],   # 하는 문서(source · target · both · pair · flow — 문서 여럿인 워크플로우만 · 그 밖은 "": ② §15 「문서마다 단위문서 TASK」)
            "beside": bool(s.get("beside")),   # 앞 줄과 같은 차례(조립한 정의의 같은 행 — ② §18-6 「행 × 두 칸」: 붙박이는 늘 거짓)
            "onText": on_text(s["on"], *names),   # 그 화면 글(문서 이름까지 — 화면이 그대로 쓴다 · on 이 비면 "")
            "cond": [{"key": k, "name": name, "text": s[k]} for k, name in COND if s[k]],   # 단계마다 조건(② §10 — 적힌 것만: 공통 모듈의 단계는 빈 목록)
            "uses": list(s["uses"]), "spec": _spec(s["spec"]),
            "modules": [{"name": m, "path": module_path(m) or "", "doc": _doc(m)} for m in s["modules"]],
            "agents": [ags.get(a) or {"id": a, "no": "", "name": a, "group": "", "role": "", "run": "", "model": None} for a in s["agents"]]}


def listing():
    """{tasks[{job, inputs, output, note, soon, prompt, roles[…], flow[…], base, stages[{id, meta, no, name, does, steps[…]}]}], common[{id, name, does, where, usedBy[job…], steps[…]}], by, change} — spec_워크플로우 ② §2.
    roles = 문서 역할마다 {role, name, title, kind, many, unit[{stage, steps[단계 key…]}]}(원본 → 목적 — unit = 그 문서의 단위문서 TASK: ② §15 「문서마다 단위문서 TASK」 · title = 역할의 화면 이름) ·
    flow = 워크플로우 전체의 단계 [{stage, steps[key…]}](on flow — 문서마다가 아니라 한 번) · base = 구성의 기준 문서 역할(source · target · None) · 단계마다 on · onText(하는 문서의 화면 글).
    조립한 것은 + custom · name · desc · premise · premiseFrom(전제를 비웠을 때 물려받는 붙박이 키)."""
    ags = _agents()
    used = {c["id"]: [] for c in COMMON}
    for t in TASKS:
        for g in _groups(t):
            for s in g["steps"]:
                for u in s["uses"]:
                    if u in used and t["job"] not in used[u]:
                        used[u].append(t["job"])
    made = custom()   # 화면에서 조립한 TASK(② §14) — 붙박이 뒤에 선다
    for c in COMMON:   # 단계 — 그 단계를 조립한 TASK(묶음의 module): 붙박이 + 조립한 TASK
        if c.get("kind") == "stage":
            used[c["id"]] = assembled(c["id"]) + [t["job"] for t in made if any(g.get("module") == c["id"] for g in _groups(t))]
        else:
            used[c["id"]] += [t["job"] for t in made if any(c["id"] in s["uses"] for g in _groups(t) for s in g["steps"]) and t["job"] not in used[c["id"]]]
    tasks = [{"job": t["job"], "inputs": t["inputs"], "output": t["output"], "note": t.get("note", ""), "soon": bool(t.get("soon")),
              **({"custom": True, "name": t["name"], "desc": t["desc"], "premise": t["premise"], "premiseFrom": t["premise_from"]} if t.get("custom") else {}),   # 조립한 TASK — 이름 · 설명은 저장소의 것(화면의 TASK_CATALOG 에 없을 수 있다) · premiseFrom = 전제를 비웠을 때 물려받는 붙박이 키
              "ways": [{"key": k, "name": name, "text": t["ways"][k]} for k, name in WAYS] if t.get("ways") else [],   # 진행 방식(한 번에 · 묻는 것 · 남기는 곳 · 단계별)
              "prompt": None if t.get("custom") else f"jobs/{t['job']}.md" if (ROOT / "jobs" / f"{t['job']}.md").is_file() else None,
              "doc": "" if t.get("custom") else f"{TASK_DIR.name}/{t['job']}.md",   # TASK 문서(② §10 — 이 TASK 의 세부: 시작 점검 · 단계마다 조건). 조립한 TASK 는 만든 글이 없다(등록부가 저장소에 있다)
              "entry": [{"when": w, "name": name, "note": note, "items": [{"key": c["key"], "name": c["name"], "by": list(c["by"]), "does": c["does"], "miss": c["miss"], "uses": list(c["uses"]), "spec": _spec(c["spec"])}
                                                                    for c in items]} for w, name, note, items in entry(t)],
              "roles": [{"role": r["role"], "name": r["name"], "title": r["title"], "kind": r["kind"], "many": r["many"],   # 문서 역할 · 그 문서의 단위문서 TASK(② §15)
                         "unit": [{"stage": g["id"], "steps": [s["key"] for s in hit]} for g, hit in unit(t, r["role"])]} for r in _roles(t)],
              "flow": [{"stage": g["id"], "steps": [s["key"] for s in hit]} for g, hit in flow_of(t)],   # 워크플로우 전체(문서마다가 아니라 한 번 — 어느 문서의 단위문서 TASK 에도 안 듦)
              "base": t.get("base"),   # 구성의 기준 문서 역할(이관 = source · 조립 = 목적 문서에 「구성 맞추기」 가 있을 때만 source · 취합 = target · 그 밖 None)
              "stages": [{"id": g["id"], "meta": g["meta"], "no": g["no"], "name": g["name"], "does": g["does"], "module": g.get("module"), "steps": [_step(s, ags, nm) for s in g["steps"]]} for g in _groups(t)]}
             for t in map(_shown, list(TASKS) + made) for nm in [_names(t)]]   # _shown = 사람이 고친 도구 이름을 얹은 사본(② §18-19)
    common = [{"id": c["id"], "kind": c.get("kind") or "", "name": c["name"], "does": c["does"], "where": c["where"], "usedBy": used[c["id"]],
               "steps": [_step(s, ags) for s in (_shown({"stages": [c]}, "relay")["stages"][0] if c.get("kind") == "stage" else c)["steps"]]} for c in COMMON]   # kind "stage" = 단계 모듈(TASK 가 조립 — ② §13)
    return {"tasks": tasks, "common": common, "by": dict(BY), "change": dict(CHANGE), "waysNote": WAYS_NOTE.replace("**", "")}


# ---------------------------------------------------------------- workflow.md — 등록부를 글로(spec_워크플로우 ② §8)
# 사용자 2026-11-15 "워크플로우는 항시 내용을 workflow.md 로 갖고 있고, 에이전트는 이걸 항시 가지고 있다가 참조하도록".
# 저장소 루트의 workflow.md = 이 등록부에서 **만든 글**(손으로 고치지 않는다 — `python -X utf8 tools/workflow_md.py` 가 다시 만들고 tests/test_workflow.py 가 견준다). CLAUDE.md 가 그 파일을 세션마다 불러온다.
MD = ROOT / "workflow.md"
TASK_DIR = ROOT / "tasks"   # TASK 문서 — tasks/<job>.md(② §10: workflow.md = 전체 지도 · TASK 문서 = 그 TASK 의 세부). 이것도 만든 글이다(task_markdown)
_CATALOG = APP / "static" / "task_catalog.js"


def catalog():
    """task_catalog.js(화면의 원본)에서 ({job: {name, desc, accept}}, {묶음 meta: {no, name}}) — TASK 이름·한 줄 설명과 이관·취합의 「N단계 이름」."""
    text = _CATALOG.read_text(encoding="utf-8")
    heads = list(re.finditer(r'^  (\w+): \{ name: "([^"]*)"', text, re.M))
    tasks = {}
    for i, m in enumerate(heads):
        seg = text[m.end(): heads[i + 1].start() if i + 1 < len(heads) else len(text)]
        d = re.search(r'\bdesc: "([^"]*)"', seg)
        a = re.search(r"\baccept: \[([^\]]*)\]", seg)   # 그 TASK 의 카드가 받는 확장자(없으면 hwp·hwpx — task_catalog.js taskAcceptOf)
        tasks[m[1]] = {"name": m[2], "desc": d[1] if d else "", "accept": [x.strip(" \"'") for x in a[1].split(",") if x.strip()] if a else ["hwp", "hwpx"]}
    block = re.search(r"const TASK_STAGE_META = Object\.freeze\(\{(.*?)\n\}\);", text, re.S)   # 그 묶음 안만 — 같은 꼴의 RELAY_STAGE_META(이관의 묶음 이름: 등록부에 no·name 으로 적는다)가 덮지 않게
    return tasks, {m[1]: {"no": m[2], "name": m[3]} for m in re.finditer(r'^  (\w+): \{ no: "([^"]*)", name: "([^"]*)"', block[1] if block else "", re.M)}


def _md_tools():
    """markdown() · task_markdown() 이 같이 쓰는 글 조각 → (cat, name(job), label(묶음), step(단계, cond=False, many=False), head(TASK)).
    step 의 cond = 단계마다 조건(COND)을 그 줄 아래에 적는가(TASK 문서만) · many = 원본 문서가 여럿인 TASK 인가(하는 문서의 이름 — on_label) ·
    head = TASK 머리의 줄들(받는 문서 · 산출물 · 문서마다 단위문서 TASK · 워크플로우 전체(문서 여럿인 TASK 만) … 전제 · 시작 점검 한 줄 · TASK 문서 경로)."""
    from app import agents
    cat, meta = catalog()

    def name(job):
        return (cat.get(job) or {}).get("name") or job

    def label(g):   # 묶음 이름 — 이관·취합은 「1단계 프로젝트 구성」(TASK_STAGE_META), 그 밖은 등록부의 이름
        m = meta.get(g["meta"]) if g["meta"] else None
        return " ".join(x for x in ((m["no"], m["name"]) if m else (g["no"], g["name"])) if x)

    def agent(a):   # 「09 자리 연결 검토」 — 등록부의 기본 작업 번호
        return f"{agents.BY_ID[a]['no']} {agents.BY_ID[a]['name']}" if a in agents.BY_ID else a

    def step(s, cond=False, many=False):
        must = not (s["optional"] or s["soon"] or s["auto"])   # 「필수」 — 화면(workflow.js badges · dashboard.js dashTags)과 같은 셈(2026-11-18 사용자 「꼭 해야하는건 필수 라고 적어줘」)
        tags = [" → ".join(BY[b] for b in s["by"]), CHANGE[s["change"]]] + [t for t, on in (("자동", s["auto"]), ("필수", must), ("선택", s["optional"]), ("준비 중", s["soon"])) if on]
        tags += [on_label(s["on"], many)] if s["on"] else []   # 하는 문서(문서 여럿인 TASK 의 단계만 — ② §15 「문서마다 단위문서 TASK」)
        more = [s["out"]] if s["out"] else []
        if s["agents"]:
            more.append("에이전트: " + " · ".join(agent(a) for a in s["agents"]))
        if s["uses"]:
            more.append("도구: " + " · ".join(BY_COMMON[u]["name"] for u in s["uses"]))   # 화면 말 「도구」 = 등록부의 COMMON(전의 「공통 모듈」 — 2026-11-19 사용자 "모듈이라고 하지 말고 공통 모듈을 도구라고 하자")
        if s["modules"]:
            more.append("코드: " + " · ".join(f"`{m}`" for m in s["modules"]))
        if s["spec"]:
            more.append(f"사양: {s['spec'][0]} {s['spec'][1]}")
        head = f"- **{' '.join(x for x in (s['no'], s['name']) if x)}** — {' · '.join(tags)}. {s['does']}"
        return [head] + ([f"  - {cname}: {s[k]}" for k, cname in COND if s[k]] if cond else []) + ([f"  → {' | '.join(more)}"] if more else [])

    def units(t):   # 「문서마다 단위문서 TASK」 한 줄(문서 여럿인 TASK 만 — ② §15): 문서 역할마다 그 문서에 닿는 묶음(단계 › 단계 …) — 목적 문서가 원본에서 받는 묶음은 「← 원본 문서」
        rs = _roles(t)
        if len(rs) < 2 or not _groups(t):
            return []
        many = _many(t)

        def one(r):
            groups = []
            for g, hit in unit(t, r["role"]):
                pair = r["role"] == "target" and any(s["on"] == "pair" for s in hit)
                groups.append(f"{label(g)}(" + (f"← {on_label('source', many)}: " if pair else "") + JOIN.join("「" + s["name"] + "」" for s in hit) + ")")
            return f"{r['title']}({r['name']}" + (" — 문서마다" if r["many"] else "") + "): " + (JOIN.join(groups) or "없음")
        return ["- 문서마다 단위문서 TASK — " + " / ".join(one(r) for r in rs)]

    def flows(t):   # 「워크플로우 전체」 한 줄(② §15 — on flow 의 단계: 문서마다가 아니라 한 번) · 구성의 기준 문서(base — 없으면 적지 않는다). 머리 · 꼬리는 「이관 조건」 과 같은 조각(FLOW_HEAD · base_text)
        rows = flow_of(t)
        if not rows:
            return []
        base = next((r for r in _roles(t) if r["role"] == t.get("base")), None)
        return [f"- {FLOW_HEAD}: " + JOIN.join(f"{label(g)}(" + JOIN.join("「" + s["name"] + "」" for s in hit) + ")" for g, hit in rows) + base_text(base)]

    def head(t, doc=True):   # TASK 머리(첫 단계 묶음 앞) — 첫 화면 에이전트의 프롬프트는 머리만 싣는다(work_guide.workflow_part). doc = TASK 문서를 가리키는 줄을 넣는가(workflow.md 만)
        out = ["- 조립: 화면에서 단계를 골라 만든 워크플로우입니다(이 PC 에 저장 — 파일로 쓰지 않음)."] if t.get("custom") else []   # 화면 절의 「조립」 줄과 같은 뜻(② §14)
        out += [f"- 받는 문서: {t['inputs']}", f"- 산출물: {t['output']}"] + units(t) + flows(t) + ([f"- 알아 둘 것: {t['note']}"] if t.get("note") else [])
        out += [f"- {wname}: {t['ways'][k]}" for k, wname in WAYS] if t.get("ways") else []
        if t.get("custom"):   # 조립한 워크플로우(② §14) — 전제는 조립할 때 적은 글이거나 틀이 같은 붙박이의 것(app/job_prompts.py — 물려받으면 고른 단계 한 줄을 붙인다)
            if t["premise"] or (ROOT / "jobs" / f"{t['premise_from']}.md").is_file():   # 물려받을 전제 파일이 없는 틀(문서 하나로 조립한 것 — 붙박이 양식 표준화 · 양식 맞추기에는 전제 파일이 없다)은 그 줄을 적지 않는다
                out.append("- 전제: 조립할 때 적은 글(이 워크플로우의 LLM 호출이 먼저 읽는 글)" if t["premise"] else
                           f"- 전제(할 일 프롬프트 — 먼저 읽는 글): `jobs/{t['premise_from']}.md`(틀이 같은 워크플로우의 것 — 그 글의 단계 설명 가운데 고르지 않은 단계는 하지 않는다)")
        elif (ROOT / "jobs" / f"{t['job']}.md").is_file():
            out.append(f"- 전제(할 일 프롬프트 — 먼저 읽는 글): `jobs/{t['job']}.md`")
        if doc and entry(t):   # 시작 점검은 때마다 항목 이름만 — 무엇을 보고 안 맞으면 어떻게 되는지는 TASK 문서(② §10)
            out.append("- 시작 점검(시작할 때 저절로 확인하는 것): " + " / ".join(f"{wname} — {' · '.join(c['name'] for c in items)}" for _, wname, _, items in entry(t)))
        if doc:
            out.append(f"- 세부(워크플로우 상세 문서 — 시작 점검 · 단계마다 조건): `{TASK_DIR.name}/{t['job']}.md`")
        return out

    return cat, name, label, step, head


def mod(g):
    """묶음이 조립한 단계 모듈을 적는 줄(없으면 빈 목록) — workflow.md · TASK 문서의 묶음 머리 아래."""
    m = BY_COMMON.get(g.get("module") or "")
    return [f"조립한 단계: {m['name']}(`{m['id']}`)", ""] if m else []


def _many_labels(ts):
    """그 워크플로우들의 단계 줄에 실제로 쓰인 「원본 문서가 여럿일 때」 의 꼬리표(_ON_MANY — 차례대로) — 「읽는 법」 이 쓰인 것만 적는다."""
    return [lab for on, lab in _ON_MANY.items() if any(_many(t) and s["on"] == on for t in ts for g in _groups(t) for s in g["steps"])]


def _read_step(on, many=()):
    """「읽는 법」 의 단계 줄 꼴 — on = 하는 문서를 적는 글인가(문서 여럿인 워크플로우가 든 글 — ② §15 「문서마다 단위문서 TASK」) ·
    many = 그 글에 쓰인 「원본 문서가 여럿일 때」 의 꼬리표(_many_labels — 「원본 문서마다」 · 「원본 문서마다 → 목적」 …)."""
    return ("`번호 이름 — 누가(차례대로) · 문서가 바뀌나 · 자동/필수/선택/준비 중" + (" · 하는 문서" if on else "") + ". 하는 일`"
            + (f"(하는 문서 = 문서 여럿인 워크플로우의 단계만 — {' · '.join(ON.values())}" + (" · 원본 문서가 여럿이면 " + " · ".join(f"「{x}」" for x in many) if many else "") + ")" if on else ""))


# ---- 업무 흐름 — workflow.md 의 손으로 쓰는 절(spec_워크플로우 ② §16 「업무 흐름」)
# 사용자 2026-11-19 (업무 흐름 넷 — 사업계획서 구성 · 구조화 · 이관 · 취합: 흐름마다 입력 · 사전조건 · 처리 · 결과 — 을 적어 주며) "이거 workflow.md 로 관리하고 싶은데 저장하고 claude.md 에 이거 명시해줘".
# workflow.md 는 등록부에서 만든 글이지만 이 절만은 사람이 쓴 글이다 — 원본은 workflow.md 의 두 표식 사이이고(등록부에 없다), markdown() 이 그 글을 파일에서 읽어 그대로 되넣는다(다시 만들어도 남는다).
# 위의 FLOW_HEAD · flow_of(「워크플로우 전체」 — 문서마다가 아니라 한 번 하는 단계)와 다른 것이다.
FLOW_TITLE = "## 업무 흐름"
FLOW_MARKS = ("<!-- 업무 흐름: 손으로 쓰는 절 — 시작 -->", "<!-- 업무 흐름: 손으로 쓰는 절 — 끝 -->")
FLOW_NOTE = ("> 이 절만은 등록부에서 만든 글이 아니라 **사용자가 직접 쓴 글**이다 — 워크플로우의 큰 흐름(무엇을 받아 무엇을 만드는가)과 문서의 이름. 아래 두 표식 사이를 이 파일에서 바로 고친다"
             "(다시 만들어도 그대로 남는다 — 표식 줄은 지우지 않는다). 사양 [spec/spec_워크플로우.md](spec/spec_워크플로우.md) ② §16.",
             "> 앱이 지금 밟는 단계 · 차례 · 조건은 아래 「한눈에」 부터의 글(등록부)이 보인다 — 이 절과 다른 곳은 아직 맞추지 않은 곳이다(같은 사양서 ④).")


def flow_text(text=None):
    """workflow.md 의 손으로 쓰는 절 「업무 흐름」 의 글(두 표식 사이 — 앞뒤 빈 줄은 뺀다). text 를 안 주면 지금 파일에서 읽는다. 파일 · 표식이 없으면 ""."""
    if text is None:
        try:
            text = MD.read_text(encoding="utf-8")
        except OSError:
            return ""
    a, b = text.find(FLOW_MARKS[0]), text.find(FLOW_MARKS[1])
    return text[a + len(FLOW_MARKS[0]):b].strip("\n") if 0 <= a < b else ""


def flow_cut(text):
    """workflow.md 의 글에서 「업무 흐름」 절(머리 줄 ~ 끝 표식)을 뺀 글 — 등록부에서 만든 글만 남는다. 그 절이 없으면 그대로.
    작업 진행 에이전트의 프롬프트가 이 글을 자른다(work_guide._sections — 아직 등록부와 맞추지 않은 흐름은 싣지 않는다: ② §16 「읽는 쪽」)."""
    a, b = text.find(FLOW_TITLE + "\n"), text.find(FLOW_MARKS[1])
    return text[:a] + text[b + len(FLOW_MARKS[1]):].lstrip("\n") if 0 <= a < b else text


def _flow_md():
    """markdown() 에 넣는 「업무 흐름」 절의 줄들 — 머리 줄 · 안내(만든 글) · 표식 사이에 지금 파일의 글(flow_text). 글이 없어도 표식은 둔다(쓸 자리)."""
    flow = flow_text()
    return ["", FLOW_TITLE, "", *FLOW_NOTE, "", FLOW_MARKS[0], ""] + ([flow, ""] if flow else []) + [FLOW_MARKS[1]]


def markdown():
    """등록부 → workflow.md 의 글. 사람의 설정(에이전트 설정에서 고친 작업 번호·모델)과 모듈 설명 글에 기대지 않는다 — 어느 PC 에서나, 등록부·task_catalog.js·에이전트 등록부·jobs/ 가 같으면 같은 글.
    하나뿐인 예외 = 「업무 흐름」 절(② §16): 그 절의 표식 사이 글은 등록부가 아니라 지금 workflow.md 에서 읽어 그대로 되넣는다(_flow_md)."""
    cat, name, label, step, head = _md_tools()
    used = {c["id"]: assembled(c["id"]) if c.get("kind") == "stage" else [t["job"] for t in TASKS if any(c["id"] in s["uses"] for g in _groups(t) for s in g["steps"])] for c in COMMON}
    out = ["# 워크플로우 전체 지도", "",
           "> 이 파일은 워크플로우 등록부 `app/workflow.py` 에서 **만든 글**이다(화면 `/workflow` 와 같은 내용) — 손으로 고치지 않는다.",
           "> 등록부를 고치면 `python -X utf8 tools/workflow_md.py` 로 다시 만든다(안 맞으면 `tests/test_workflow.py` 가 떨어진다). 사양 [spec/spec_워크플로우.md](spec/spec_워크플로우.md) ② §8.",
           ">",
           "> 워크플로우는 여러 단계를 정해진 차례로 밟는 일이다 — 단계는 도구를 쓴다. 스크립트가 계산하고 LLM 은 검토 · 판정만 하며, 문서는 사람이 확인(「반영」 · 「한 번에 진행」)한 뒤에만 바뀐다.",
           "> " + WAYS_NOTE,
           f"> 읽는 법 — 단계 = {_read_step(True, _many_labels(TASKS))}, 그 아래 `→` 줄 = 나오는 것 | 에이전트(작업 번호 이름) | 도구 | 코드(`app/<이름>.py`) | 사양 자리.",
           "> 문서 여럿인 워크플로우(원본 문서 → 목적 문서)는 머리의 「문서마다 단위문서 TASK」 에 문서마다 그 문서에 하는 묶음(단계 › 단계 …)을 적는다 — 원본 문서는 그 워크플로우에서 바뀌지 않고, "
           "목적 문서가 원본 문서에서 내용을 받는 묶음에는 「← 원본 문서」 를 붙인다. 준비 · 프로젝트 구성처럼 문서마다가 아니라 한 번 하는 단계는 「워크플로우 전체」 줄에 따로 적는다"
           "(그 단계 줄의 하는 문서 = 「워크플로우 전체」 · 구성의 기준 문서도 그 줄에).",
           f"> 이음 기호 — 「{JOIN.strip()}」 = 다음(묶음 사이에도, 한 묶음 안의 단계 사이에도). 단계 이름 안의 「 · 」(「헤딩 · 표 분석」)는 이름의 일부다.",
           f"> 이 글은 모든 워크플로우의 차례를 보이는 **전체 지도**다 — 워크플로우 하나의 세부(시작할 때 저절로 확인하는 것 · 단계마다 조건)는 **워크플로우 상세 문서** `{TASK_DIR.name}/<워크플로우 키>.md` 에 있다(같은 등록부에서 만든 글).",
           *_flow_md(),   # 「업무 흐름」 — 손으로 쓰는 절(② §16): 머리 안내 바로 아래 · 「한눈에」 앞
           "", "## 한눈에", "", "| 워크플로우 | 키 | 단계 묶음 |", "|---|---|---|"]
    for t in TASKS:
        out.append(f"| {name(t['job'])} | `{t['job']}` | {' › '.join(label(g) for g in _groups(t)) or '준비 중'} |")
    out += ["", "단계: " + " · ".join(f"{c['name']}(`{c['id']}`)" for c in COMMON if c.get("kind") == "stage"),
            "", "도구: " + " · ".join(f"{c['name']}(`{c['id']}`)" for c in COMMON if c.get("kind") != "stage"), "", "## 워크플로우"]
    for t in TASKS:
        out += ["", f"### {name(t['job'])} — `{t['job']}`" + (" (준비 중)" if t.get("soon") else ""), ""]
        if (cat.get(t["job"]) or {}).get("desc"):
            out += [cat[t["job"]]["desc"], ""]
        out += head(t)   # 받는 문서 · 산출물 · 문서마다 단위문서 TASK · 알아 둘 것 · 진행 방식 넷 · 전제 · 시작 점검 한 줄 · TASK 문서 경로 — TASK 머리(첫 단계 묶음 앞)에 둔다
        for g in _groups(t):
            out += ["", f"#### {label(g)} — {g['does']}", ""] + mod(g)
            for s in g["steps"]:
                out += step(s, many=_many(t))
    heads = {True: ["", "## 단계", "", "워크플로우가 조립하는 일반 단계(문서 검토 → 구성 맞추기 → 내용 넣기 → 문서 정리) — 워크플로우의 묶음이 「조립한 단계」 로 가리킨다. 이 절의 단계 글은 문서 이름만 일반 이름(원본 문서 · 목적 문서)이다."],
             False: ["", "## 도구", "", "워크플로우에 묶이지 않고 여러 워크플로우가 쓰는 과정 — 워크플로우의 단계가 「도구」 로 가리킨다."]}
    for c in COMMON:   # 단계 넷이 먼저(COMMON 의 맨 앞), 그 뒤 도구
        stage = c.get("kind") == "stage"
        out += heads.pop(stage, [])
        out += ["", f"### {c['name']} — `{c['id']}`", "", c["does"], "", f"- 여는 곳: {c['where']}",
                f"- {'조립한 워크플로우' if stage else '쓰는 워크플로우'}: {' · '.join(name(j) for j in used[c['id']]) or ('아직 없음' if stage else '어느 워크플로우의 문서에서나 연다(단계에 묶이지 않음)')}", ""]
        for s in c["steps"]:
            out += step(s)
    return "\n".join(out) + "\n"


# ---------------------------------------------------------------- tasks/<job>.md — TASK 문서(spec_워크플로우 ② §10)
# workflow.md 의 그 TASK 절(머리 · 단계)을 그대로 담고, 그 위에 **시작 점검**(시작할 때 저절로 확인하는 것)과 **단계마다 조건**을 더한 글.
# 작업 진행 에이전트는 작업 화면에서 이 글을 그 TASK 의 절로 읽는다(work_guide.workflow_part — 참조 글).
def task_md(job):
    """그 TASK 의 TASK 문서 경로(`tasks/<job>.md`)."""
    return TASK_DIR / f"{job}.md"


def task_markdown(job):
    """등록부 → 그 TASK 의 TASK 문서 글. markdown() 과 같은 원천(등록부 · task_catalog.js · 에이전트 등록부 · jobs/)만 쓴다 — 어느 PC 에서나 같은 글.
    조립한 워크플로우(app/custom_tasks.py 의 키 — ② §14)도 같은 꼴로 만든다(assemble — 고른 단계만 · 이름 · 설명은 저장소의 것). 그 글은 파일로 쓰지 않는다(task_docs 는 붙박이만) —
    작업 진행 에이전트가 그 키의 참조 글로 바로 읽는다(work_guide.task_doc_text). 모르는 키는 KeyError."""
    t = task_of(job)
    if t is None:
        raise KeyError(job)
    cat, name, label, step, head = _md_tools()
    made = bool(t.get("custom"))
    out = [f"# {t['name'] if made else name(job)} — `{job}`" + (" (준비 중)" if t.get("soon") else ""), ""]
    if made:
        out += ["> 이 글은 조립한 워크플로우(이 PC 의 저장소 — `app/custom_tasks.py`)를 워크플로우 등록부 `app/workflow.py` 가 바로 글로 옮긴 것이다(파일로 쓰지 않는다 — 화면 `/workflow` 의 이 워크플로우 절과 같은 내용).",
                "> 사양 [spec/spec_워크플로우.md](../spec/spec_워크플로우.md) ② §14 · §15.", ""]
    else:
        out += ["> 이 파일은 워크플로우 등록부 `app/workflow.py` 에서 **만든 글**이다(워크플로우 상세 문서 — 화면 `/workflow` 의 이 워크플로우 절과 같은 내용) — 손으로 고치지 않는다.",
                "> 등록부를 고치면 `python -X utf8 tools/workflow_md.py` 로 다시 만든다(안 맞으면 `tests/test_workflow.py` 가 떨어진다). 사양 [spec/spec_워크플로우.md](../spec/spec_워크플로우.md) ② §10.",
                ">",
                "> [워크플로우 전체 지도](../workflow.md) 가 모든 워크플로우의 차례를 보인다면 이 글은 이 워크플로우 하나의 **세부**다 — 시작할 때 저절로 확인하는 것(시작 점검)과 단계마다 조건을 함께 적는다.", ""]
    desc = t.get("desc") if made else (cat.get(job) or {}).get("desc")
    if desc:
        out += [desc, ""]
    out += head(t, doc=False)
    if t.get("soon") or not _groups(t):
        return "\n".join(out) + "\n"
    out += ["", "## 시작 점검 — 시작할 때 저절로 확인하는 것", "",
            "읽는 법 — 항목 = `이름 — 누가. 무엇을 확인하나`, 그 아래 `안 맞으면` = 그때 어떻게 되나, `→` 줄 = 도구 | 사양 자리. 사람이 누르지 않아도 보는 것만 적는다(끝의 「저절로 돌지 않는 것」 은 헷갈리기 쉬운 것을 따로 적은 것)."]
    for _, wname, note, items in entry(t):   # 조립한 워크플로우도 그 글을 싣는다(assemble 의 entry — 붙박이 이관의 시작 점검을 이 조립의 묶음 번호로: _relay_entry)
        out += ["", f"### {wname}", "", note, ""]
        for c in items:
            more = (["도구: " + " · ".join(BY_COMMON[u]["name"] for u in c["uses"])] if c["uses"] else []) + ([f"사양: {c['spec'][0]} {c['spec'][1]}"] if c["spec"] else [])
            out += [f"- **{c['name']}** — {' → '.join(BY[b] for b in c['by'])}. {c['does']}"] + ([f"  - 안 맞으면: {c['miss']}"] if c["miss"] else []) + ([f"  → {' | '.join(more)}"] if more else [])
    out += ["", "## 단계마다 조건", "",
            f"읽는 법 — 단계 = {_read_step(len(_roles(t)) > 1, _many_labels([t]))}, 그 아래 " + " · ".join(f"`{cname}`" for _, cname in COND)
            + "(적을 것이 있을 때만), `→` 줄 = 나오는 것 | 에이전트(작업 번호 이름) | 도구 | 코드(`app/<이름>.py`) | 사양 자리.",
            "「끝난 것으로 보는 때」 는 화면이 지금 문서의 상태로 셈한다 — 단추를 눌렀다는 사실로 끝남을 적지 않는다."]
    for g in _groups(t):
        out += ["", f"### {label(g)} — {g['does']}", ""] + mod(g)
        for s in g["steps"]:
            out += step(s, cond=True, many=_many(t))
    uses = list(dict.fromkeys(u for g in _groups(t) for s in g["steps"] for u in s["uses"]))
    if uses:
        out += ["", "## 쓰는 도구", "", "단계가 「도구」 로 가리키는 과정 — 그 과정의 단계는 [워크플로우 전체 지도](../workflow.md) 의 「도구」 절에 있다.", ""]
        out += [f"- **{BY_COMMON[u]['name']}**(`{u}`) — {BY_COMMON[u]['does']}" for u in uses]
    return "\n".join(out) + "\n"


def task_docs():
    """만들어야 할 TASK 문서 전부 → {경로: 글} — tools/workflow_md.py 가 쓰고 tests/test_workflow.py 가 견준다(TASK 마다 하나 · 준비 중인 TASK 도 머리만)."""
    return {task_md(t["job"]): task_markdown(t["job"]) for t in TASKS}
